const icon=(name,extra='')=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" ${extra}><path d="${paths[name==='path'?'pen':name]||paths.rect}"/></svg>`;
const NS='http://www.w3.org/2000/svg';
const STORAGE='rash-studio-project-v1';
// The document is authoritative. The editor view only redirects scope-local fields.
// Enumerable accessors remain structuredClone-safe for existing atomic model helpers.
let rootProject,project,editScopeId=null,scopeTrail=[],hasProjectWork=false;
const scopedFields=new Set(['name','width','height','duration','camera','nodes']);
function editingDefinition(){return rootProject.symbols?.find(symbol=>symbol.id===editScopeId);}
function refreshEditingScope(){
 if(editScopeId&&!editingDefinition()){editScopeId=null;scopeTrail=[];}
 if(!editScopeId){project=rootProject;return;}
 project={};
 for(const key of Object.keys(rootProject))Object.defineProperty(project,key,{enumerable:true,configurable:true,
  get:()=>key==='background'?'transparent':key==='symbols'?symbolDependencies():scopedFields.has(key)?editingDefinition()[key]:rootProject[key],
  set:value=>{if(key==='background')return;if(scopedFields.has(key))editingDefinition()[key]=value;else rootProject[key]=value;}});
}
function replaceDocument(next){rootProject=next;refreshEditingScope();}
try{replaceDocument(parseProject(localStorage.getItem(STORAGE)||''));hasProjectWork=true;}catch{replaceDocument(createProject());}
let selectedId=null,frame=0,playing=false,loop=true,tool='select',grid=true,zoom=1,inspectorTab='properties',history=[],future=[],drag=null,clipboard=null,game=null,gameSnapshot=null,runtime=null,runtimeError=null;
let saveTimer,toastTimer,raf=0,lastTick=0,frameAccumulator=0,modalKind='',previewSVG=null,searchTicket=0;
let gameInput={left:false,right:false,up:false,down:false};
const stage=$('#stage');
function selected(){return project.nodes.find(n=>n.id===selectedId);}
const isMobile=()=>matchMedia('(max-width:780px), (max-width:1000px) and (pointer:coarse)').matches;
function canEdit(){if(!selected()){notify('Select a layer first.');return false;}if(selected().locked){notify('Unlock this layer before editing.');return false;}return true;}
function renderSelectionActions(){const n=selected();$('#selection-actions').hidden=!n;$('#selection-hint').hidden=!!n;$('#selection-toolbar [data-action="delete"]').disabled=!!n?.locked;$('#selection-toolbar [data-action="undo"]').disabled=!history.length;$('#selection-toolbar [data-action="redo"]').disabled=!future.length;}
function closePanels(){for(const id of ['#left-panel','#right-panel'])$(id).classList.remove('mobile-open');$('#panel-backdrop').hidden=true;$$('.mobile-nav [aria-expanded]').forEach(b=>{b.setAttribute('aria-expanded','false');b.classList.remove('active');});}
function openPanel(panel){closePanels();if(!isMobile())return;$(panel).classList.add('mobile-open');$('#panel-backdrop').hidden=false;const b=$(`.mobile-nav [aria-controls="${panel.slice(1)}"]`);b?.setAttribute('aria-expanded','true');b?.classList.add('active');}
function openInspector(tab='properties'){stopPlayback();inspectorTab=tab;renderInspector();openPanel('#right-panel');$('#inspector').scrollTop=0;}
function editTextDialog(){if(!canEdit()||selected().type!=='text')return;openModal(`${modalHeader('Edit text','Your changes apply when you choose Apply text.')}<div class="modal-body"><label class="form-label" for="edit-text-input">TEXT CONTENT</label><textarea id="edit-text-input" class="text-input" aria-label="Text content" maxlength="5000" rows="5">${esc(selected().text)}</textarea></div><div class="modal-footer"><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="apply-text">Apply text</button></div>`,'text');}

// Graphic symbols share one definition and inherit their parent's deterministic clock.
function symbolDependencies(){const ids=new Set(),visit=nodes=>{for(const node of nodes)if(node.type==='symbol'&&!ids.has(node.symbolId)){ids.add(node.symbolId);const definition=rootProject.symbols?.find(item=>item.id===node.symbolId);if(definition)visit(definition.nodes);}};visit(editingDefinition()?.nodes||[]);return (rootProject.symbols||[]).filter(item=>ids.has(item.id));}
function symbolUsage(id){return [rootProject,...rootProject.symbols||[]].reduce((sum,scope)=>sum+scope.nodes.filter(node=>node.type==='symbol'&&node.symbolId===id).length,0);}
function wouldCycle(id){if(!editScopeId)return false;const seen=new Set(),visit=value=>{if(value===editScopeId)return true;if(seen.has(value))return false;seen.add(value);return (rootProject.symbols?.find(item=>item.id===value)?.nodes||[]).some(node=>node.type==='symbol'&&visit(node.symbolId));};return visit(id);}
function renderScopeNavigation(){const definition=editingDefinition();$('#scope-breadcrumb').hidden=!definition;$('#scope-name').textContent=definition?.name||'';$('#parent-scope').hidden=scopeTrail.length<2;$('.scene-label').textContent=definition?`Symbol: ${definition.name}`:'Scene 01';$('#app').classList.toggle('editing-symbol',!!definition);}
function showScopeLayers(){$$('[data-panel]').forEach(button=>{const active=button.dataset.panel==='layers';button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));});$('#layers-panel').hidden=false;$('#library-panel').hidden=true;}
function enterSymbol(id){finishLiveEdit();stopPlayback();const definition=rootProject.symbols?.find(item=>item.id===id);if(!definition)return notify('This symbol no longer exists.');if(editScopeId===id){closePanels();return;}scopeTrail.push({id:editScopeId,selection:selectedId,frame});editScopeId=id;refreshEditingScope();selectedId=null;frame=0;zoom=1;motionProperty='all';showScopeLayers();closeModal();closePanels();render();notify(`Editing ${definition.name}. Changes update every instance.`);}
function leaveSymbol(all=false){finishLiveEdit();stopPlayback();const destination=all?scopeTrail[0]:scopeTrail.pop();if(all)scopeTrail=[];editScopeId=destination?.id||null;refreshEditingScope();selectedId=project.nodes.some(node=>node.id===destination?.selection)?destination.selection:null;frame=clamp(destination?.frame||0,0,project.duration-1);zoom=1;motionProperty='all';showScopeLayers();closeModal();closePanels();render();}
function showSymbolLibrary(){stopPlayback();$$('[data-panel]').forEach(button=>{const active=button.dataset.panel==='library';button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));});$('#layers-panel').hidden=true;$('#library-panel').hidden=false;renderLibrary($('#library-search').value);openPanel('#left-panel');}
function renderSymbols(query=$('#library-search')?.value||''){const list=$('#symbol-library');if(!list)return;const definitions=(rootProject.symbols||[]).filter(item=>item.name.toLowerCase().includes(query.toLowerCase()));list.innerHTML=definitions.map(symbol=>{const used=symbolUsage(symbol.id),cycle=wouldCycle(symbol.id);return `<article class="symbol-card" data-symbol-row="${esc(symbol.id)}"><div class="symbol-card-heading">${icon('symbol')}<strong>${esc(symbol.name)}</strong><span>${used} instance${used===1?'':'s'}</span></div><p>${symbol.nodes.length} layers · ${symbol.duration} frames · ${(symbol.duration/rootProject.fps).toFixed(1)}s</p><div class="symbol-card-actions">${[['place','Place instance'],['edit','Edit symbol'],['rename','Rename'],['delete','Delete definition']].map(([action,label])=>`<button data-symbol-action="${action}" data-symbol-id="${esc(symbol.id)}" ${action==='place'&&cycle?'disabled aria-describedby="symbol-cycle-'+esc(symbol.id)+'"':''} aria-label="${label}: ${esc(symbol.name)}">${label}</button>`).join('')}</div>${cycle?`<p class="symbol-cycle-note" id="symbol-cycle-${esc(symbol.id)}">Cannot place here: that would create a circular symbol reference.</p>`:''}</article>`;}).join('')||`<p class="symbol-empty">${rootProject.symbols?.length?'No symbols match your search.':'Create reusable artwork with its own timeline. Edit once to update every instance.'}</p>`;const convert=$('#library-convert-symbol');if(convert)convert.disabled=!selected()||!!selected().locked;}
let symbolDialogMode='new',symbolDialogId=null;
function symbolDialog(mode='new',id=null){if(mode==='convert'&&!canEdit())return;symbolDialogMode=mode;symbolDialogId=id;const definition=rootProject.symbols?.find(item=>item.id===id),name=mode==='rename'?definition?.name:mode==='convert'?selected().name+' symbol':'New symbol';openModal(`${modalHeader(mode==='rename'?'Name this symbol':mode==='convert'?'Convert to a graphic symbol':'Create a graphic symbol','A shared SVG definition with a deterministic timeline. Every instance reflects edits to its definition.')}<div class="modal-body"><label class="form-label" for="symbol-name">SYMBOL NAME</label><input id="symbol-name" class="text-input" maxlength="100" aria-label="Symbol name" value="${esc(name)}"/><p class="form-hint">${mode==='convert'?'The selected layer and its animation become the symbol content. Its replacement instance keeps the same appearance and position.':mode==='new'?'The new symbol starts empty at the current canvas size and duration. Use the familiar drawing tools, layers and timeline inside it.':'Instance names remain independent of the library name.'}</p><p class="text-danger" id="symbol-error" role="alert"></p></div><div class="modal-footer"><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="confirm-symbol">${mode==='rename'?'Save symbol name':'Create symbol'}</button></div>`,'symbol');}
function confirmSymbol(){const name=$('#symbol-name').value.trim()||'Untitled symbol';let createdId;const ok=change(()=>{if(symbolDialogMode==='rename'){const definition=rootProject.symbols?.find(item=>item.id===symbolDialogId);if(!definition)throw new Error('This symbol no longer exists.');definition.name=name;}else if(symbolDialogMode==='convert'){const result=convertNodesToSymbol(rootProject,[selectedId],name,{scopeId:editScopeId||undefined});createdId=result.symbolId;selectedId=result.instanceId;}else createdId=createSymbol(rootProject,name,{width:project.width,height:project.height,duration:project.duration});});if(!ok){$('#symbol-error').textContent=$('#toast').textContent;return;}const mode=symbolDialogMode;closeModal();if(mode==='new')enterSymbol(createdId);else if(mode==='convert'){openInspector('properties');notify('Graphic symbol created. Edit symbol updates every instance.');}else notify('Symbol renamed.');}
function placeSymbol(id){let instanceId;if(change(()=>{instanceId=addSymbolInstance(rootProject,id,{scopeId:editScopeId||undefined});selectedId=instanceId;})){closePanels();setTool('select');openInspector('properties');notify('Another instance added. Its transform and playback are independent.');}}
function deleteSymbol(id){const name=rootProject.symbols?.find(item=>item.id===id)?.name;if(change(()=>removeSymbolDefinition(rootProject,id))){notify(`${name||'Symbol'} definition deleted. Undo restores it.`);}}
function symbolProperties(node){const definition=rootProject.symbols?.find(item=>item.id===node.symbolId);if(!definition)return '';return `<div class="property-section symbol-properties"><h3>Graphic symbol <span class="pill">SHARED</span></h3><p class="symbol-definition-name">${esc(definition.name)}</p><button class="button primary" data-action="edit-symbol">${icon('symbol')} Edit symbol</button><button class="button" data-action="symbol-library">Open symbol library</button><p class="property-note">Editing the definition changes all ${symbolUsage(definition.id)} instances. Each instance keeps its own transform and playback.</p><label class="field full-field"><span>Playback</span><select data-property="playback" aria-label="Symbol playback">${[['loop','Loop'],['once','Play once'],['single','Hold one frame']].map(([value,label])=>`<option value="${value}" ${node.playback===value?'selected':''}>${label}</option>`).join('')}</select></label><div class="field-grid symbol-playback-fields"><label class="field"><span>First</span><input data-property="firstFrame" aria-label="First symbol frame" type="number" min="1" max="${definition.duration}" value="${node.firstFrame+1}"/></label><label class="field"><span>Start</span><input data-property="startFrame" aria-label="Start on parent frame" type="number" min="1" max="36001" value="${node.startFrame+1}"/></label></div><p class="property-note">First selects the symbol frame. Start anchors its clock to the parent timeline. Before Start, the first frame holds. Current symbol frame: ${evaluateSymbolFrame(node,frame,definition)+1} of ${definition.duration}. Graphic symbols have no independent MovieClip events or scripts.</p></div>`;}

function currentNode(){return evaluateScene(project,frame).find(n=>n.id===selectedId);}
function isGame(){return !editScopeId&&project.nodes.some(n=>n.name==='player')&&project.nodes.some(n=>n.name.startsWith('energy-'));}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400);}
let liveEdit=null;
const appliedInputs=new WeakMap();
const controlValue=input=>input.type==='checkbox'?String(input.checked):input.value;
function setControlValue(input,value){if(input.type==='checkbox')input.checked=!!value;else input.value=String(value);appliedInputs.set(input,controlValue(input));}
const HISTORY_BYTES=20*1024*1024;
function historyEntry(){return {serialized:serializeProject(rootProject),scopeId:editScopeId,trail:structuredClone(scopeTrail),selection:selectedId,frame};}
function trimHistory(){while(history.length+future.length>80 || [...history,...future].reduce((sum,item)=>sum+item.serialized.length*2,0)>HISTORY_BYTES){if(history.length)history.shift();else future.shift();}}
function checkpoint(){hasProjectWork=true;future=[];const snapshot=historyEntry();if(snapshot.serialized.length*2<=HISTORY_BYTES){history.push(snapshot);trimHistory();}}
function restore(snapshot){stopPlayback();editScopeId=snapshot.scopeId;scopeTrail=structuredClone(snapshot.trail);replaceDocument(parseProject(snapshot.serialized));selectedId=project.nodes.some(n=>n.id===snapshot.selection)?snapshot.selection:null;frame=Math.min(snapshot.frame,project.duration-1);game=null;render();scheduleSave();}
function undo(){finishLiveEdit();if(!history.length)return notify('You are at the beginning of your history.');const snapshot=history.pop();future.push(historyEntry());trimHistory();restore(snapshot);notify('Change undone');}
function redo(){finishLiveEdit();if(!future.length)return notify('No changes to redo.');const snapshot=future.pop();history.push(historyEntry());trimHistory();restore(snapshot);notify('Change restored');}
function scheduleSave(){clearTimeout(saveTimer);$('#save-status').innerHTML='<i></i> Saving locally';saveTimer=setTimeout(()=>{try{localStorage.setItem(STORAGE,serializeProject(gameSnapshot||rootProject));$('#save-status').innerHTML='<i></i> Saved on this device';}catch{$('#save-status').textContent='Export a copy to save';notify('Device storage is unavailable. Use File → Save project for a backup.');}},300);}
function commit(){replaceDocument(validateProject(rootProject));game=null;render();scheduleSave();}
function change(fn){finishLiveEdit();const before=cloneProject(rootProject),past=history.slice(),next=future.slice(),selection=selectedId,scope=editScopeId,trail=scopeTrail.slice(),beforeFrame=frame;checkpoint();try{fn();commit();return true;}catch(error){editScopeId=scope;scopeTrail=trail;replaceDocument(before);history=past;future=next;selectedId=selection;frame=beforeFrame;render();notify(error.message);return false;}}
function timecode(f=frame){const sec=Math.floor(f/project.fps);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}:${String(f%project.fps).padStart(2,'0')}`;}
function fitStage(){const area=$('#stage-area'),w=area.clientWidth,h=area.clientHeight;const style=getComputedStyle(area),spaceX=parseFloat(style.paddingLeft)+parseFloat(style.paddingRight),spaceY=parseFloat(style.paddingTop)+parseFloat(style.paddingBottom);const ratio=Math.min(Math.max(10,w-spaceX)/project.width,Math.max(10,h-spaceY)/project.height);const wrap=$('#stage-surround');wrap.style.width=`${project.width*ratio*zoom}px`;wrap.style.height=`${project.height*ratio*zoom}px`;$('#zoom-label').textContent=zoom===1?'Fit':`${Math.round(ratio*zoom*100)}%`;}
function renderStage(){renderScene(stage,project,frame,{selectedId:playing?null:selectedId,onSelect:(id)=>{if(tool==='select'&&!drag)selectNode(id);}});if(previewSVG)renderScene(previewSVG,project,frame);$('#stage-overlay').setAttribute('viewBox',`0 0 ${project.width} ${project.height}`);$('#render-count').textContent=`${project.nodes.filter(n=>n.visible).length} objects`;$('#frame-status').textContent=`Frame ${frame+1} of ${project.duration}`;$('#timecode').textContent=timecode();const previewTime=$('#preview-time');if(previewTime)previewTime.textContent=timecode();updatePlayhead();}
function render({preserveInspector=false}={}){if(!preserveInspector)liveEdit=null;renderSelectionActions();document.title=`${rootProject.name} · Rash Studio`;$('.project-name').textContent=rootProject.name;renderScopeNavigation();renderSymbols();$('#artboard-name').textContent=project.name;$('#artboard-size').textContent=`${project.width} × ${project.height}`;setControlValue($('#fps-select'),project.fps);renderLayers();if(!preserveInspector)renderInspector();renderTimeline();renderStage();fitStage();$('#selection-status').textContent=selected()?`${selected().name} · ${selected().type==='symbol'?'Graphic symbol':selected().type==='mesh'?'3D mesh':selected().type==='text'?'Text':'Vector shape'}`:'Select an object to start creating';$('#timeline-summary').textContent=`${project.nodes.length} layers · ${(project.duration/project.fps).toFixed(1)}s`;}
function selectNode(id){finishLiveEdit();if(id!==selectedId)motionProperty='all';selectedId=id;renderSymbols();renderSelectionActions();renderLayers();renderInspector();renderTimeline();renderStage();$('#selection-status').textContent=selected()?`${selected().name} · ${selected().type==='symbol'?'Graphic symbol':selected().type==='mesh'?'3D mesh':selected().type==='text'?'Text':'Vector shape'}`:'Select an object to start creating';}
function renderLayers(){const list=$('#layer-list');list.innerHTML=project.nodes.length?[...project.nodes].reverse().map(n=>`<div class="layer-item ${n.id===selectedId?'selected':''} ${!n.visible?'is-hidden':''} ${n.locked?'is-locked':''}" data-layer="${esc(n.id)}" tabindex="0" role="button" aria-label="Select ${esc(n.name)}" aria-pressed="${n.id===selectedId}">${icon(n.type==='path'?'pen':n.type)}<span class="layer-name" title="Select layer to edit">${esc(n.name)}</span><div class="layer-controls"><button data-layer-action="edit" data-id="${esc(n.id)}" aria-label="Edit ${esc(n.name)}" title="Edit layer">${icon('settings')}</button><button data-layer-action="visibility" data-id="${esc(n.id)}" class="${!n.visible?'is-off':''}" aria-label="${n.visible?'Hide':'Show'} ${esc(n.name)}" title="${n.visible?'Hide':'Show'} layer">${icon(n.visible?'eye':'eyeOff')}</button><button data-layer-action="lock" data-id="${esc(n.id)}" class="${n.locked?'is-locked':''}" aria-label="${n.locked?'Unlock':'Lock'} ${esc(n.name)}" title="${n.locked?'Unlock':'Lock'} layer">${icon(n.locked?'lock':'unlock')}</button></div></div>`).join(''):'<div class="blank-state">An open canvas.<br/>Choose a drawing tool to make your first mark.</div>';}
const primitiveNames={box:'Box',sphere:'Sphere',torus:'Torus',pyramid:'Pyramid'};
function primitiveArt(type){const shapes={box:'M40 20 74 39 74 77 40 96 6 77 6 39Z M6 39 40 58 74 39 M40 58V96',sphere:'M40 20a38 38 0 1 0 0 76 38 38 0 0 0 0-76 M2 58h76 M40 20C12 36 12 80 40 96 M40 20C68 36 68 80 40 96 M10 36Q40 50 70 36 M10 80Q40 66 70 80',torus:'M3 58C3 9 77 9 77 58S3 107 3 58 M23 58C23 36 57 36 57 58S23 80 23 58 M3 58 23 58 M57 58 77 58 M40 21V42 M40 75V95',pyramid:'M40 17 79 82 40 102 1 82Z M40 17V102 M1 82 40 63 79 82'};return `<svg class="primitive-art" viewBox="-10 6 100 110" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round" aria-hidden="true"><path d="${shapes[type]}"/></svg>`;}
function primitiveButtons(){return Object.entries(primitiveNames).map(([id,name])=>`<button class="primitive-choice" data-primitive="${id}" aria-label="Add 3D ${name.toLowerCase()}">${primitiveArt(id)}<strong>${name}</strong><span>Add to scene</span></button>`).join('');}
function threeWorkspaceDialog(){openModal(`${modalHeader('Give your ideas another dimension.','Real 3D geometry, projected into an editable SVG scene.')}<div class="modal-body"><div class="dimension-intro"><div><span class="eyebrow">DIMENSION STUDIO</span><h3>Shape. Light. Move.</h3><p>Build with four primitives. Animate rotation and depth. Keep every face crisp at any size.</p></div>${primitiveArt('torus')}</div><div class="primitive-grid">${primitiveButtons()}</div><p id="three-error" class="text-danger" role="alert"></p><div class="dimension-actions"><button class="button" data-action="camera">${icon('mesh')} Camera settings</button><button class="button" data-action="motion-presets" ${selected()?'':'disabled'}>${icon('spark')} Motion presets</button></div><p class="code-info">The scene camera affects 3D objects. Text and vector layers keep their canvas positions. Use the Properties panel to rotate, recolor or switch to wireframe.</p></div><div class="modal-footer"><button class="button" data-action="close-modal">Back to canvas</button><button class="button primary" data-template="dimension">Open dimension template</button></div>`,'three');}
function addMesh(primitive){if(!Object.hasOwn(primitiveNames,primitive))return;const ok=change(()=>{const n=addNode(project,'mesh');Object.assign(n,{primitive,name:`${primitiveNames[primitive]} ${project.nodes.length}`,width:220,height:220,x:project.width/2-110,y:project.height/2-110,rotationX:-18,rotationY:28,fill:'#f16b43'});selectedId=n.id;});if(ok){closeModal();setTool('select');openInspector('properties');notify(`${primitiveNames[primitive]} added. Rotate it in 3D transform.`);}else if($('#three-error'))$('#three-error').textContent=$('#toast').textContent;}
function meshProperties(n){return `<div class="property-section mesh-properties"><h3>3D transform <span class="pill">THREE.JS</span></h3><div class="field-grid">${field('X°','rotationX',n.rotationX,'°',-100000,100000)}${field('Y°','rotationY',n.rotationY,'°',-100000,100000)}${field('Z','z',n.z,'',-300,300)}<label class="field"><select data-property="primitive" aria-label="3D primitive">${Object.entries(primitiveNames).map(([id,name])=>`<option value="${id}" ${n.primitive===id?'selected':''}>${name}</option>`).join('')}</select></label></div><label class="property-toggle">Wireframe <input type="checkbox" data-property="wireframe" aria-label="Wireframe" ${n.wireframe?'checked':''}/></label><button class="button" data-action="camera">${icon('mesh')} Scene camera</button><p class="property-note">Rotation and depth can be keyframed. Camera settings apply to every 3D object.</p></div>`;}
const maskShapeLabels={none:'None',rect:'Rectangle',ellipse:'Ellipse'};
function maskProperties(n){const disabled=n.maskType==='none';return `<div class="property-section mask-properties"><h3>Reveal mask <span class="section-caption">${frame?'FRAME '+(frame+1):'LOCAL SPACE'}</span></h3><label class="field mask-shape-field"><span>Shape</span><select data-property="maskType" aria-label="Mask shape">${MASK_TYPES.map(value=>`<option value="${value}" ${n.maskType===value?'selected':''}>${maskShapeLabels[value]}</option>`).join('')}</select></label><div class="field-grid mask-fields">${field('X','maskX',n.maskX,'',-100000,100000)}${field('Y','maskY',n.maskY,'',-100000,100000)}${field('W','maskWidth',n.maskWidth,'',0,10000)}${field('H','maskHeight',n.maskHeight,'',0,10000)}${field('∠','maskRotation',n.maskRotation,'°',-100000,100000)}</div><p class="property-note mask-note">${disabled?'Choose a shape or fit a mask to begin.':'Mask values follow the current frame. A zero size hides the layer; Layers keeps it editable.'}</p><button class="button" data-action="fit-mask">${icon('resize')} Fit mask to layer</button><button class="button danger-button" data-action="remove-mask" ${disabled?'disabled':''}>${icon('trash')} Remove mask</button><button class="button" data-action="animate-mask">${icon('diamond')} Animate mask</button></div>`;}
function syncMaskControls(){const node=selected();if(!node)return;const disabled=node.maskType==='none';$$('#inspector .mask-fields [data-property]').forEach(input=>input.disabled=disabled||!!node.locked);const remove=$('#inspector [data-action="remove-mask"]');if(remove)remove.disabled=disabled||!!node.locked;const note=$('#inspector .mask-note');if(note)note.textContent=disabled?'Choose a shape or fit a mask to begin.':'Mask values follow the current frame. A zero size hides the layer; Layers keeps it editable.';}
function fitSelectedMask(){if(!canEdit())return;if(change(()=>fitNodeMask(project,selectedId,frame)))notify(`Mask fitted at frame ${frame+1}`);}
function removeSelectedMask(){if(!canEdit()||selected().maskType==='none')return;if(change(()=>removeNodeMask(project,selectedId)))notify('Mask and its animation removed. Undo restores both.');}
function effectProperties(n){const symbol=n.type==='symbol',effectField=(label,prop)=>field(label,prop,n[prop],'px',0,30).replace('type="number"',`type="number" ${symbol?'disabled aria-describedby="symbol-effects-note"':''}`);return `<div class="property-section"><h3>Effects <span class="pill">LIVE</span></h3><div class="field-grid">${effectField('Blur','blur')}${effectField('Glow','glow')}</div><label class="field full-field blend-field"><span>Blend</span><select data-property="blendMode" aria-label="Blend mode">${['normal','multiply','screen','overlay'].map(v=>`<option value="${v}" ${n.blendMode===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label><p class="property-note" ${symbol?'id="symbol-effects-note"':''}>${symbol?'Blur and glow are not supported on symbol instances. Edit the symbol and apply effects to its individual layers. Instance blending remains available.':'Keyframe blur and glow for reveals and atmospheric transitions.'}</p></div>`;}
const timingLabels={linear:'Linear',easeIn:'Ease in',easeOut:'Ease out',easeInOut:'Ease in and out',step:'Hold',bezier:'Custom Bezier',bounce:'Bounce',elastic:'Elastic'};
const motionPropertyLabels={x:'X position',y:'Y position',width:'Width',height:'Height',rotation:'Rotation',opacity:'Opacity',scale:'Scale',rotationX:'3D rotation X',rotationY:'3D rotation Y',z:'3D depth',blur:'Blur',glow:'Glow',maskX:'Mask X',maskY:'Mask Y',maskWidth:'Mask width',maskHeight:'Mask height',maskRotation:'Mask rotation'};
let motionProperty='all';
function timingContext(key=selected()?.keyframes.find(k=>k.frame===frame)){const authored=!!key&&(motionProperty==='all'||Number.isFinite(key[motionProperty])),timing=key?keyframeTiming(key,motionProperty):{easing:'linear'},base=key?keyframeTiming(key,'all'):timing;const mixed=!!key&&motionProperty==='all'&&ANIMATED_PROPERTIES.some(prop=>Number.isFinite(key[prop])&&JSON.stringify(keyframeTiming(key,prop))!==JSON.stringify(base));return {key,authored,timing,mixed};}
function canEditTiming(){if(!canEdit())return false;const {key,authored}=timingContext();if(!key||!authored){notify(key?'This property has no value at this keyframe. Add a value before editing its timing.':'Select a keyframe to edit its timing.');return false;}return true;}
function motionPropertyOptions(node){const authored=ANIMATED_PROPERTIES.filter(prop=>node.keyframes.some(key=>Number.isFinite(key[prop]))||(node.maskType!=='none'&&MASK_PROPERTIES.includes(prop)));return `<option value="all">All properties</option>${authored.map(prop=>`<option value="${prop}">${motionPropertyLabels[prop]}</option>`).join('')}`;}
function cameraDialog(){const c=evaluateCamera(project.camera,frame),key=project.camera.keyframes.find(k=>k.frame===frame);openModal(`${modalHeader('Find your angle.','Animate one perspective camera across your 3D composition.')}<div class="modal-body"><div class="camera-diagram">${primitiveArt('box')}<span>SCENE CAMERA</span>${icon('mesh')}</div><div class="camera-timing-bar"><label><span class="form-label">CAMERA FRAME</span><input id="camera-frame" aria-label="Camera frame" class="text-input" type="number" min="1" max="${project.duration}" value="${frame+1}"/></label><label><span class="form-label">EASING INTO THIS POSE</span><select id="camera-easing" aria-label="Camera easing" class="text-input">${Object.entries(timingLabels).map(([value,label])=>`<option value="${value}" ${(key?.easing||'easeInOut')===value?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="form-row camera-pose-fields">${[['yaw','Yaw',-180,180,'°'],['pitch','Pitch',-180,180,'°'],['distance','Distance',500,2000,''],['fov','Field of view',20,90,'°']].map(([id,label,min,max,unit])=>`<label><span class="form-label">${label.toUpperCase()} ${unit}</span><input id="camera-${id}" aria-label="Camera ${label.toLowerCase()}" class="text-input" type="number" value="${round(c[id])}" min="${min}" max="${max}" step="any"/></label>`).join('')}</div><p class="code-info">The fields show the evaluated pose at this frame. Set camera keyframe saves these values at this frame. Apply camera changes the base pose and preserves existing keys; authored keys take precedence.</p><div class="camera-key-actions"><button class="button primary" data-action="set-camera-keyframe">${icon('diamond')} Set camera keyframe</button><button class="button danger-button" data-action="remove-camera-keyframe" ${key?'':'disabled'}>Remove camera keyframe</button></div><div id="camera-keyframes" class="keyframe-list" aria-label="Camera keyframes"></div><p id="camera-status" class="camera-status" role="status"></p><p id="camera-error" class="text-danger" role="alert"></p></div><div class="modal-footer"><button class="button" data-action="close-modal">Close</button><button class="button" data-action="apply-camera">Apply camera</button></div>`,'camera');syncCameraControls();}
function cameraError(message){const error=$('#camera-error');if(error)error.textContent=message;else notify(message);}
function readCameraDraft(){const inputs=CAMERA_PROPERTIES.map(k=>$(`#camera-${k}`));if(!inputs.every(input=>input?.value.trim()&&input.checkValidity()&&Number.isFinite(Number(input.value)))){cameraError('Enter camera values within the displayed ranges.');return null;}return Object.fromEntries(CAMERA_PROPERTIES.map(k=>[k,Number($(`#camera-${k}`).value)]));}
function syncCameraControls({preserveFrame=false}={}){if(modalKind!=='camera'||!$('#camera-frame'))return;const c=evaluateCamera(project.camera,frame),keys=project.camera.keyframes,key=keys.find(k=>k.frame===frame);if(!preserveFrame)setControlValue($('#camera-frame'),frame+1);$('#camera-frame').max=project.duration;for(const property of CAMERA_PROPERTIES)setControlValue($(`#camera-${property}`),Math.round(c[property]*1000)/1000);setControlValue($('#camera-easing'),key?.easing||'easeInOut');const keyList=$('#camera-keyframes'),signature=keys.map(k=>k.frame).join(',');if(keyList.dataset.frames!==signature){keyList.dataset.frames=signature;keyList.innerHTML=keys.map(k=>`<button class="keyframe-chip ${k.frame===frame?'active':''}" data-camera-seek="${k.frame}" aria-label="Go to camera keyframe ${k.frame+1}">◇ ${k.frame+1}</button>`).join('')||'<span class="property-note">No camera keys yet. Save a pose to start moving.</span>';}$$('[data-camera-seek]').forEach(button=>button.classList.toggle('active',Number(button.dataset.cameraSeek)===frame));$('#modal [data-action="remove-camera-keyframe"]').disabled=!key;$('#camera-status').textContent=key?`Camera keyframe at frame ${frame+1}. Edit the pose and choose Set camera keyframe to update it.`:`Evaluated camera at frame ${frame+1}. ${keys.length} camera ${keys.length===1?'keyframe':'keyframes'}.`;}
function applyCamera(){const values=readCameraDraft();if(!values)return;if(change(()=>project.camera={...project.camera,...values})){closeModal();notify('Base camera updated. Existing camera keyframes are preserved.');}else cameraError($('#toast').textContent);}
function setCameraKey(){const values=readCameraDraft(),input=$('#camera-frame');if(!values)return;if(!input.value.trim()||!input.checkValidity())return cameraError('Choose a frame inside the composition.');const target=Number(input.value)-1,existing=project.camera.keyframes.find(k=>k.frame===target),easing=$('#camera-easing').value,timing={easing,...(easing==='bezier'?{bezier:existing?.bezier||[.25,.1,.25,1]}:{})};if(change(()=>addCameraKeyframe(project,target,values,timing))){$('#camera-error').textContent='';syncCameraControls();}else cameraError($('#toast').textContent);}
function removeCameraKey(){if(!project.camera.keyframes.some(k=>k.frame===frame))return;if(change(()=>project.camera.keyframes=project.camera.keyframes.filter(k=>k.frame!==frame))){$('#camera-error').textContent='';syncCameraControls();}else cameraError($('#toast').textContent);}
function cameraFrameInput(input){if(input.id!=='camera-frame')return false;if(appliedInputs.get(input)===controlValue(input))return true;if(input.value.trim()===''||!Number.isFinite(Number(input.value)))return true;finishLiveEdit();frame=clamp(Math.round(Number(input.value))-1,0,project.duration-1);appliedInputs.set(input,controlValue(input));renderStage();renderInspector();syncCameraControls({preserveFrame:true});return true;}
let chosenMotion='fadeIn';
function supportsMotionPreset(p,node){return (!p.meshOnly||node.type==='mesh')&&(p.id!=='blurReveal'||node.type!=='symbol');}
function motionPresetDialog(initial='fadeIn'){if(!canEdit())return;const available=motionPresets.filter(p=>supportsMotionPreset(p,selected()));chosenMotion=available.some(p=>p.id===initial)?initial:'fadeIn';openModal(`${modalHeader('Motion with a little intention.','Editable keyframes, expressive timing, no hidden animation.')}<div class="modal-body"><div class="motion-catalog">${available.map((p,i)=>`<button class="motion-choice ${p.id===chosenMotion?'selected':''}" data-motion-preset="${p.id}" aria-pressed="${p.id===chosenMotion}"><span class="motion-glyph motion-glyph-${p.id}">${({wipeReveal:'▥',irisReveal:'◉'})[p.id]||['◌','↗','◉','◈','≈','✦'][i]||'◇'}</span><strong>${esc(p.name)}</strong><small>${esc(p.description)}</small></button>`).join('')}</div><div class="form-row motion-timing"><label><span class="form-label">DURATION IN SECONDS</span><input class="text-input" id="motion-duration" aria-label="Motion duration in seconds" type="number" value="1" min="${1/project.fps}" max="${Math.min(600,36000/project.fps)}" step="any"/></label><label><span class="form-label">DELAY FROM PLAYHEAD</span><input class="text-input" id="motion-delay" aria-label="Motion delay in seconds" type="number" value="0" min="0" max="600" step=".1"/></label></div><label class="property-toggle">Apply to all unlocked layers <input id="motion-all" type="checkbox"/></label><label class="field"><span>Stagger</span><input id="motion-stagger" aria-label="Stagger in seconds" type="number" min="0" max="60" value=".1" step=".1"/><span class="field-unit">seconds per layer</span></label><p class="code-info">Starts at frame ${frame+1} plus the delay. The preset replaces its animated properties in this interval. Unrelated properties and keys outside it remain. Presets change timing only for their animated properties. Other property curves are preserved. Spin in 3D applies only to mesh layers. Focus reveal applies only to individual artwork layers; edit a symbol to apply it inside. Apply to all skips layers that do not support the selected recipe. A preset must fit inside the composition.</p><p id="motion-error" class="text-danger" role="alert"></p></div><div class="modal-footer"><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="apply-motion-preset">Apply motion</button></div>`,'motion-preset');}
function applySelectedMotionPreset(){if(!canEdit())return;const duration=$('#motion-duration'),delay=$('#motion-delay'),stagger=$('#motion-stagger'),all=$('#motion-all').checked;if(![duration,delay,stagger].every(i=>i.value.trim()&&i.checkValidity())){$('#motion-error').textContent='Enter a valid duration, delay and stagger.';return;}const ids=all?project.nodes.filter(n=>!n.locked&&supportsMotionPreset(motionPresets.find(p=>p.id===chosenMotion),n)).map(n=>n.id):[selectedId],startFrame=frame+Math.round(Number(delay.value)*project.fps),durationFrames=Math.max(1,Math.round(Number(duration.value)*project.fps)),offset=all?Math.round(Number(stagger.value)*project.fps):0;if(startFrame+durationFrames+Math.max(0,ids.length-1)*offset>=project.duration){$('#motion-error').textContent='This motion runs past the composition. Shorten its duration or delay, reduce stagger, or extend the timeline.';return;}if(change(()=>applyMotionPreset(project,ids,chosenMotion,{startFrame,durationFrames,stagger:offset}))){closeModal();seek(startFrame);openInspector('motion');notify(`Motion applied to ${ids.length} ${ids.length===1?'layer':'layers'}`);}else $('#motion-error').textContent=$('#toast').textContent;}
const curvePresets=[['Smooth',[.42,0,.58,1]],['Snappy',[.16,1,.3,1]],['Overshoot',[.34,1.56,.64,1]]];
function curveEditor(key){return `<div class="property-section curve-editor"><h3>Timing graph <span class="pill">BEZIER</span></h3><p class="property-note">Drag either handle, or enter exact coordinates. Choose a motion property to give it its own timing. All properties replaces timing for the entire keyframe.</p><svg id="curve-graph" viewBox="0 0 240 200" role="img" aria-label="Editable Bezier timing graph" ${!key?'class="is-disabled"':''}><path d="M24 36H216M24 100H216M24 164H216M24 36V164M120 36V164M216 36V164" class="curve-grid"/><path d="M24 164 216 36" class="curve-reference"/><path id="curve-arms" class="curve-arms"/><path id="curve-path" class="curve-path"/><circle cx="24" cy="164" r="3" fill="#68745c"/><circle cx="216" cy="36" r="3" fill="#68745c"/>${[0,1].map(i=>`<g data-curve-handle="${i}" aria-label="Bezier handle ${i+1}"><circle r="20" fill="transparent"/><circle r="6" class="curve-handle"/></g>`).join('')}<text x="24" y="190">TIME</text><text x="24" y="20">PROGRESS</text></svg><div class="curve-values">${['X1','Y1','X2','Y2'].map((l,i)=>`<label class="field"><span>${l}</span><input type="number" data-bezier="${i}" aria-label="Bezier ${l.toLowerCase()}" value="${(key?.bezier||[.25,.1,.25,1])[i]}" min="${i%2?-2:0}" max="${i%2?3:1}" step=".01" ${key?'':'disabled'}/></label>`).join('')}</div><div class="curve-presets">${curvePresets.map(([name,values])=>`<button data-curve-preset="${JSON.stringify(values)}" ${key?'':'disabled'}>${name}</button>`).join('')}</div><span class="curve-caption" id="curve-caption">${key?'Select Custom Bezier or move a handle to use this curve.':'Add or select a keyframe to edit its timing.'}</span></div>`;}
function syncCurveControls(){const graph=$('#curve-graph');if(!graph)return;const node=selected(),{key,timing,authored,mixed}=timingContext(),disabled=!authored||node.locked,b=timing.bezier||[.25,.1,.25,1],x=v=>24+v*192,y=v=>164-v*128;graph.classList.toggle('is-disabled',disabled);const curve=key&&timing.easing!=='bezier'?Array.from({length:65},(_,i)=>`${i?'L':'M'}${x(i/64)} ${y(ease(i/64,timing.easing))}`).join(' '):`M24 164C${x(b[0])} ${y(b[1])} ${x(b[2])} ${y(b[3])} 216 36`;$('#curve-path').setAttribute('d',curve);$('#curve-arms').setAttribute('d',`M24 164L${x(b[0])} ${y(b[1])}M216 36L${x(b[2])} ${y(b[3])}`);$$('[data-curve-handle]').forEach((h,i)=>h.setAttribute('transform',`translate(${x(b[i*2])},${y(b[i*2+1])})`));$$('[data-bezier]').forEach((input,i)=>{input.disabled=disabled;if(document.activeElement!==input)setControlValue(input,b[i]);});$$('[data-curve-preset]').forEach(input=>input.disabled=disabled);$('#curve-caption').textContent=!authored?key?'This property has no value at this keyframe. Choose an authored property.':'Add or select a keyframe to edit its timing.':mixed?'Default curve shown. Individual properties have different timing. Editing All properties replaces every override.':timing.easing==='bezier'?`${motionProperty==='all'?'All properties':motionPropertyLabels[motionProperty]} curve: ${b.map(v=>Math.round(v*100)/100).join(', ')}`:`${timingLabels[timing.easing]||timing.easing} timing shown. Move a handle to switch to Custom Bezier.`;}
let curveDrag=null;
function moveCurveHandle(event){if(!curveDrag)return;try{const graph=$('#curve-graph');if(!graph)return;const r=graph.getBoundingClientRect(),x=(event.clientX-r.left)/r.width*240,y=(event.clientY-r.top)/r.height*200,key=selected()?.keyframes.find(k=>k.frame===frame);if(!key)return;const bezier=[...(keyframeTiming(key,curveDrag.property).bezier||[.25,.1,.25,1])];bezier[curveDrag.handle*2]=Math.round(clamp((x-24)/192,0,1)*100)/100;bezier[curveDrag.handle*2+1]=Math.round(clamp((164-y)/128,-.25,1.25)*100)/100;setKeyframeTiming(key,curveDrag.property,{easing:'bezier',bezier});replaceDocument(validateProject(rootProject));render({preserveInspector:true});syncMotionControls();}catch(error){const failed=curveDrag;curveDrag=null;try{$('#curve-graph')?.releasePointerCapture(event.pointerId);}catch{}rollbackGesture(failed?.transaction,error);}}
document.addEventListener('pointerdown',event=>{const h=event.target.closest('[data-curve-handle]');if(!h||!canEditTiming())return;event.preventDefault();const transaction=captureGesture();checkpoint();curveDrag={handle:Number(h.dataset.curveHandle),pointerId:event.pointerId,transaction,property:motionProperty};$('#curve-graph').setPointerCapture(event.pointerId);moveCurveHandle(event);});
document.addEventListener('pointermove',event=>{if(curveDrag?.pointerId===event.pointerId){event.preventDefault();moveCurveHandle(event);}});
function finishCurveDrag(event){if(curveDrag?.pointerId!==event.pointerId)return;const done=curveDrag;curveDrag=null;try{$('#curve-graph')?.releasePointerCapture(event.pointerId);}catch{}try{commit();}catch(error){rollbackGesture(done.transaction,error);}}
document.addEventListener('pointerup',finishCurveDrag);document.addEventListener('pointercancel',finishCurveDrag);

const field=(label,prop,value,unit='',min='',max='')=>`<label class="field"><span>${label}</span><input type="number" data-property="${prop}" aria-label="${({x:'X position',y:'Y position',width:'Width',height:'Height',rotation:'Rotation',fontSize:'Font size',strokeWidth:'Stroke width',rx:'Corner radius',scale:'Scale',rotationX:'3D rotation X',rotationY:'3D rotation Y',z:'3D depth',blur:'Blur',glow:'Glow',maskX:'Mask X',maskY:'Mask Y',maskWidth:'Mask width',maskHeight:'Mask height',maskRotation:'Mask rotation'})[prop]||label}" value="${round(value??0)}" step="${prop==='scale'?'.1':'1'}" ${min!==''?`min="${min}"`:''} ${max!==''?`max="${max}"`:''}/>${unit?`<span class="field-unit">${unit}</span>`:''}</label>`;
function renderInspector(){liveEdit=null;const box=$('#inspector');const node=selected(),n=currentNode();$$('[data-inspector]').forEach(b=>{b.classList.toggle('active',b.dataset.inspector===inspectorTab);b.setAttribute('aria-selected',String(b.dataset.inspector===inspectorTab));});
 if(inspectorTab==='motion'){if(!node){box.innerHTML=`<div class="motion-empty">${icon('diamond')}Select a layer to give it a little momentum. Add keyframes, change position, and choose how the motion feels.</div><div class="property-section"><h3>Composition timing</h3>${documentTiming()}<p class="property-note">Each keyframe records the object’s position, size, rotation, scale and opacity.</p></div>`;return;}const key=node.keyframes.find(k=>k.frame===frame);box.innerHTML=`<div class="property-section"><h3 class="selected-name">${icon(node.type)}${esc(node.name)}</h3><span class="node-kind">${node.keyframes.length} keyframes · Frame ${frame+1}</span></div><div class="property-section"><h3>Playhead</h3><div class="frame-controls"><button class="button" data-action="previous-frame" aria-label="Previous frame">‹</button><label class="field"><span>Frame</span><input id="current-frame" aria-label="Current frame" type="number" min="1" max="${project.duration}" value="${frame+1}"/></label><button class="button" data-action="next-frame" aria-label="Next frame">›</button></div></div><div class="property-section motion-preset-entry"><h3>Motion recipes <span class="pill">${motionPresets.filter(p=>supportsMotionPreset(p,node)).length} PRESETS</span></h3><p class="property-note">Give a layer an entrance, a turn, or a little atmosphere.</p><button class="button primary" data-action="motion-presets">${icon('spark')} Browse motion presets</button></div><div class="property-section"><h3>Keyframes <span class="pill">TWEENED</span></h3><p class="property-note">Move the playhead, add a keyframe, then adjust the object. Rash fills in the motion.</p><button class="button" data-action="add-keyframe">${icon('diamond')} Add keyframe here</button><div class="keyframe-list">${node.keyframes.map(k=>`<button class="keyframe-chip ${k.frame===frame?'active':''}" data-seek="${k.frame}" aria-label="Go to keyframe ${k.frame+1}">◇ ${k.frame+1}</button>`).join('')}</div></div><div class="property-section"><h3>Easing into this frame</h3><label class="motion-property-field"><span class="field-label">Motion property</span><select id="motion-property" aria-label="Motion property" class="easing-select">${motionPropertyOptions(node)}</select></label><select class="easing-select" id="easing-select" aria-label="Keyframe easing" ${key?'':'disabled'}><option value="mixed" disabled>Mixed property timing</option>${[['linear','Linear'],['easeIn','Ease in'],['easeOut','Ease out'],['easeInOut','Ease in and out'],['step','Hold'],['bezier','Custom Bezier'],['bounce','Bounce'],['elastic','Elastic']].map(([v,l])=>`<option value="${v}" ${key?.easing===v?'selected':''}>${l}</option>`).join('')}</select><p class="property-note">${key?'Controls the transition into the selected keyframe.':'Select an existing keyframe to edit its easing.'}</p><div class="keyframe-time-field" ${key?'':'hidden'}><label class="field"><span>At</span><input id="keyframe-time" type="number" min="1" max="${project.duration}" value="${frame+1}" aria-label="Keyframe position"/><span class="field-unit">frame</span></label></div><button class="button danger-button" data-action="remove-keyframe" ${key?'':'hidden'}>Remove this keyframe</button></div>${curveEditor(key)}<div class="property-section"><h3>Composition timing</h3>${documentTiming()}</div>`;applyInspectorLocks(node);syncMotionControls();return;}
 if(!node){box.innerHTML=`<div class="property-section"><h3>${editScopeId?'Symbol definition':'Composition'} <span class="pill">SVG NATIVE</span></h3><div class="document-preview" style="aspect-ratio:${project.width}/${project.height}"><span>${project.width} × ${project.height}</span></div><label class="field full-field"><span>${icon('folder')}</span><input data-document="name" type="text" aria-label="${editScopeId?'Symbol definition name':'Project name'}" maxlength="${editScopeId?100:120}" value="${esc(project.name)}" /></label><div class="field-grid" style="margin-top:8px"><label class="field"><span>W</span><input data-document="width" aria-label="Canvas width" type="number" value="${project.width}" min="${editScopeId?1:16}" max="${editScopeId?10000:4096}"/></label><label class="field"><span>H</span><input data-document="height" aria-label="Canvas height" type="number" value="${project.height}" min="${editScopeId?1:16}" max="${editScopeId?10000:4096}"/></label></div><button class="button" data-action="resize">${icon('resize')} Resize composition</button></div><div class="property-section" ${editScopeId?'hidden':''}><h3>Background</h3><label class="field color-field"><input data-document="background" aria-label="Background color" type="color" value="${/^#[a-f\d]{6}$/i.test(project.background)?project.background:'#111522'}"/><span class="color-value">${esc(project.background.toUpperCase())}</span><span class="field-unit" style="margin-left:auto">100%</span></label></div><div class="property-section"><h3>Playback</h3>${documentTiming()}${editScopeId?'<p class="property-note">Duration belongs to this symbol. FPS is shared by the complete document. Return to Scene to preview all instances.</p>':''}<label class="property-toggle">Loop animation <input id="loop-inspector" type="checkbox" ${loop?'checked':''}/></label></div><div class="property-section"><h3>Scene camera <span class="pill">3D</span></h3><p class="property-note">Set the view for every 3D object in this composition.</p><button class="button" data-action="camera">${icon('mesh')} Camera settings</button><button class="button" data-action="three-workspace">Add a 3D object</button></div><div class="property-section"><h3>Ready for the web</h3><p class="property-note">A responsive, interactive composition. Export once and bring it to any website.</p><button class="button" data-action="share">${icon('code')} Get embed code</button></div>`;return;}
 box.innerHTML=`<div class="property-section"><h3 class="selected-name">${icon(node.type==='path'?'pen':node.type)}<button data-action="rename-layer" aria-label="Rename layer" title="Rename layer"><span>${esc(node.name)}</span><small class="rename-label">Rename</small></button></h3><span class="node-kind">${node.type==='symbol'?'Graphic symbol':node.type==='mesh'?'3D '+node.primitive:node.type==='text'?'Editable text':'Vector shape'} · ${node.keyframes.length?'Animated':'Static'}</span></div><div class="property-section"><h3>Transform <span class="section-caption">${frame?'FRAME '+(frame+1):'ABSOLUTE'}</span></h3><div class="alignment-buttons">${[['left','alignLeft'],['center','alignCenter'],['right','alignRight'],['top','alignTop'],['middle','alignMiddle'],['bottom','alignBottom']].map(([a,i])=>`<button data-align="${a}" title="Align ${a} to stage" aria-label="Align ${a} to stage">${icon(i)}</button>`).join('')}</div><div class="field-grid">${field('X','x',n.x)}${field('Y','y',n.y)}${field('W','width',n.width,'',1,10000)}${field('H','height',n.height,'',1,10000)}${field('∠','rotation',n.rotation,'°')}${field('↗','scale',n.scale??1,'×',.001,100)}</div></div>${node.type==='symbol'?symbolProperties(n):''}${node.type==='mesh'?meshProperties(n):''}${node.type==='text'?`<div class="property-section"><h3>Typography</h3><button class="button" data-action="edit-text" aria-label="Edit text content">Edit text content</button><textarea data-property="text" aria-label="Text content" class="font-textarea" maxlength="5000">${esc(node.text)}</textarea><div class="field-grid" style="margin-top:8px">${field('Aa','fontSize',n.fontSize,'px',1,1000)}<label class="field"><select data-property="fontWeight" aria-label="Font weight">${[400,500,600,700,800,900].map(w=>`<option ${node.fontWeight===w?'selected':''} value="${w}">${w}</option>`).join('')}</select></label></div></div>`:''}<div class="property-section ${node.type==='symbol'?'symbol-appearance':''}"><h3>Appearance</h3>${node.type==='symbol'?'<p class="property-note">Instance opacity affects all its content. Edit the symbol to change individual fills and strokes.</p>':''}<div class="field-label">Fill</div><label class="field color-field"><input type="color" data-property="fill" aria-label="Fill color" value="${/^#[a-f\d]{6}$/i.test(node.fill)?node.fill:'#ff6b35'}"/><span class="color-value">${esc(node.fill.toUpperCase())}</span><button style="margin-left:auto;font-size:8px;color:#92a07f" data-action="toggle-fill" title="Toggle fill">${node.fill==='none'?'Enable':'None'}</button></label><div class="field-label">Stroke</div><div class="field-grid"><label class="field color-field"><input type="color" data-property="stroke" aria-label="Stroke color" value="${/^#[a-f\d]{6}$/i.test(node.stroke)?node.stroke:'#555555'}"/><span class="color-value">${node.stroke==='none'?'NONE':esc(node.stroke.toUpperCase())}</span></label>${field('↔','strokeWidth',node.strokeWidth,'',0,100)}</div><div class="field-label">Opacity</div><div class="slider-field"><input data-property="opacity" type="range" min="0" max="1" step=".01" value="${n.opacity}" aria-label="Opacity"/><span>${Math.round(n.opacity*100)}%</span></div>${node.type==='rect'?`<div class="field-label">Corner radius</div>${field('⌜','rx',node.rx??0,'px',0,1000)}`:''}</div>${maskProperties(n)}${effectProperties(n)}<div class="property-section"><h3>Arrange</h3><div class="field-grid"><button class="button" data-action="bring-forward">${icon('arrowUp')} Forward</button><button class="button" data-action="send-backward">${icon('arrowDown')} Backward</button></div><div class="field-grid"><button class="button" data-action="duplicate">${icon('copy')} Duplicate</button><button class="button danger-button" data-action="delete">${icon('trash')} Delete</button></div><button class="button" data-action="motion-inspector">${icon('diamond')} Animate this layer</button><button class="button" data-action="convert-symbol">${icon('symbol')} Convert to symbol</button></div>`;applyInspectorLocks(node);syncMaskControls();}
function applyInspectorLocks(node){if(!node?.locked)return;$('#inspector').insertAdjacentHTML('afterbegin',`<div class="locked-notice"><span>${icon('lock')} This layer is locked</span><button class="button" data-action="unlock-layer">Unlock layer</button></div>`);$$('#inspector [data-property],#inspector [data-align],#inspector #easing-select,#inspector [data-bezier],#inspector [data-curve-preset],#inspector #keyframe-time,#inspector [data-action]').forEach(b=>{if(['rename-layer','edit-text','toggle-fill','bring-forward','send-backward','delete','add-keyframe','remove-keyframe','motion-presets','fit-mask','remove-mask','animate-mask','convert-symbol'].includes(b.dataset.action)||b.matches('[data-property],[data-align],#easing-select,[data-bezier],[data-curve-preset],#keyframe-time'))b.disabled=true;});}
function setProjectFPS(value){const previous=rootProject.fps,next=clamp(Math.round(Number(value)||30),1,120),ratio=next/previous;rootProject.fps=next;for(const scope of [rootProject,...rootProject.symbols||[]]){scope.duration=Math.max(1,Math.round(scope.duration*ratio));if(scope.duration>36000)throw new Error('Changing FPS would exceed the 36,000 frame timeline limit. Shorten the scene or symbol duration first.');for(const track of [...scope.nodes,scope.camera])track.keyframes=track.keyframes.map(k=>({...k,frame:Math.min(scope.duration-1,Math.round(k.frame*ratio))}));for(const node of scope.nodes)if(node.type==='symbol'){node.firstFrame=Math.round(node.firstFrame*ratio);node.startFrame=Math.round(node.startFrame*ratio);if(node.firstFrame>36000||node.startFrame>36000)throw new Error('Changing FPS would exceed the symbol playback offset limit. Reduce the offsets first.');}}frame=Math.min(project.duration-1,Math.round(frame*ratio));}
function documentTiming(){return `<div class="field-grid"><label class="field"><span>FPS</span><input type="number" data-document="fps" aria-label="Playback frames per second" value="${project.fps}" min="1" max="120"/></label><label class="field"><span>◷</span><input type="number" data-document="seconds" aria-label="Duration in seconds" value="${round(project.duration/project.fps)}" min="${1/project.fps}" max="${Math.min(600,36000/project.fps)}" step="any"/><span class="field-unit">s</span></label></div>`;}
function setNodeProperty(prop,value){const node=selected();if(!node||node.locked)return;if(prop==='maskType'&&value==='none'){removeNodeMask(project,node.id);return;}if(MASK_PROPERTIES.includes(prop)&&frame>0){let key=node.keyframes.find(k=>k.frame===frame);if(!key){if(node.keyframes.length>=1000)throw new Error('A layer supports at most 1,000 keyframes');key={frame,easing:'easeInOut'};node.keyframes.push(key);node.keyframes.sort((a,b)=>a.frame-b.frame);}key[prop]=value;return;}const anim=ANIMATED_PROPERTIES;if(anim.includes(prop)&&frame>0){const key=addKeyframe(project,node.id,frame);key[prop]=value;}else{node[prop]=value;const key=node.keyframes.find(k=>k.frame===0);if(key&&anim.includes(prop))key[prop]=value;}if(prop==='stroke'&&node.strokeWidth===0)node.strokeWidth=1;}
function renderTimeline(){
 const cameraKeys=project.camera?.keyframes||[],order=[...(cameraKeys.length?[{id:'__rash_camera__',name:'Camera',type:'mesh',cameraTrack:true,visible:true,keyframes:cameraKeys}]:[]),...[...project.nodes].reverse()];
 $('#timeline-labels').innerHTML=order.map(n=>n.cameraTrack?`<button class="track-label camera-track-label" data-action="camera" aria-label="Scene camera timeline">${icon('mesh')}<span>Camera</span><i class="track-dot"></i></button>`:`<div class="track-label ${n.id===selectedId?'selected':''}" data-layer="${esc(n.id)}" tabindex="0" role="button" aria-label="Select timeline ${esc(n.name)}">${icon(n.type==='path'?'pen':n.type)}<span>${esc(n.name)}</span><i class="track-dot"></i></div>`).join('');
 const rowHeight=isMobile()?36:29,headerHeight=isMobile()?30:26,svg=$('#timeline-svg'),width=Math.max(620,$('#tracks-scroll').clientWidth),height=Math.max(headerHeight+order.length*rowHeight,130);svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.setAttribute('width',width);svg.setAttribute('height',height);svg.style.width=`${width}px`;const duration=project.duration/project.fps,step=duration>25?5:duration>12?2:1;let markup=`<rect width="${width}" height="${height}" fill="#fafbf5"/><rect width="${width}" height="${headerHeight}" fill="#f7f9ef"/>`;
 for(let s=0;s<duration;s+=step){const x=12+s/duration*(width-24);markup+=`<path d="M${x} 23V${height}" stroke="#e9edde" stroke-width="1"/><text x="${x+3}" y="16" fill="#a6b392" font-size="8" font-family="Inter,Arial">${s===0?'00:00':s+'s'}</text>`;for(let m=1;m<4;m++){const xx=x+m*step/4/duration*(width-24);if(xx<width-12)markup+=`<path d="M${xx} 21v4" stroke="#c7d0b8"/>`;}}
 order.forEach((n,i)=>{const y=headerHeight+i*rowHeight,color=n.cameraTrack?'#bcced2':n.id===selectedId?'#f6a36f':n.type==='text'?'#d7dfb8':n.type==='ellipse'?'#d5dfc9':'#dfdabb';markup+=`<path d="M0 ${y+rowHeight}H${width}" stroke="#edf0e3"/>${n.id===selectedId?`<rect x="0" y="${y}" width="${width}" height="${rowHeight}" fill="#f9f0e5"/>`:''}<rect x="13" y="${y+8}" width="${width-28}" height="13" rx="3" fill="${color}" opacity="${n.visible?'.6':'.2'}"/>`;n.keyframes.forEach(k=>{const x=12+k.frame/(project.duration-1||1)*(width-24),attrs=n.cameraTrack?`data-camera-keyframe="${k.frame}"`:`data-keyframe="${k.frame}" data-node="${esc(n.id)}"`;markup+=`<path ${attrs} d="m${x} ${y+9} 5 5-5 5-5-5Z" fill="${n.cameraTrack?'#668d99':n.id===selectedId?'#d97242':'#91a375'}" stroke="#fff" stroke-width=".65"/>`;});});markup+=`<g id="playhead" pointer-events="none"><path d="M0 24V${height}" stroke="#dc7048" stroke-width="1"/><path d="M-5 1H5V17L0 22-5 17Z" fill="#f16b43"/></g>`;svg.innerHTML=markup;updatePlayhead();
}
function updatePlayhead(){const head=$('#playhead'),svg=$('#timeline-svg');if(head){const width=Number(svg.getAttribute('width'))||620;head.setAttribute('transform',`translate(${12+frame/(project.duration-1||1)*(width-24)},0)`);}}
function seek(value){frame=clamp(Math.round(value),0,project.duration-1);renderStage();renderInspector();syncCameraControls();}
function stopPlayback(){playing=false;cancelAnimationFrame(raf);if(gameSnapshot){replaceDocument(gameSnapshot);gameSnapshot=null;game=null;render();}$('#play-button').innerHTML=icon('play');$('#play-button').setAttribute('aria-label','Play animation');const b=$('#preview-play');if(b)b.innerHTML=`${icon('play')} Play`;}
function togglePlayback(){if(playing){stopPlayback();return;}if(frame>=project.duration-1)frame=0;if(isGame()){if(!game){gameSnapshot=cloneProject(rootProject);game=createGame(project);}if(game.status==='won'||game.status==='lost')game.reset();}playing=true;lastTick=performance.now();frameAccumulator=0;$('#play-button').innerHTML=icon('pause');$('#play-button').setAttribute('aria-label','Pause animation');const b=$('#preview-play');if(b)b.innerHTML=`${icon('pause')} Pause`;raf=requestAnimationFrame(tick);}
function tick(now){if(!playing)return;const dt=Math.min((now-lastTick)/1000,.1);lastTick=now;if(game&&isGame()){game.step(dt,gameInput);if(game.status==='won'||game.status==='lost'){const status=game.status,score=game.score;stopPlayback();notify(status==='won'?`All signals collected. Score ${score}.`:`Signal lost. Score ${score}. Press play to try again.`);}}else{frameAccumulator+=dt*project.fps;const advance=Math.floor(frameAccumulator);frameAccumulator-=advance;frame+=advance;if(frame>=project.duration){if(loop)frame%=project.duration;else{frame=project.duration-1;stopPlayback();}}}renderStage();if(playing)raf=requestAnimationFrame(tick);}
function setTool(value){tool=value;closePanels();$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));stage.style.cursor=tool==='select'?'default':tool==='hand'?'grab':'crosshair';$('#selection-status').textContent=tool==='select'?'Select and drag an object':tool==='hand'?'Drag to pan the stage':tool==='text'?'Click the stage to add text':`Drag on the stage to draw a ${tool==='path'?'freehand path':tool}`;}
function pointFromEvent(event,svg=stage){const r=svg.getBoundingClientRect();return {x:(event.clientX-r.left)/r.width*project.width,y:(event.clientY-r.top)/r.height*project.height};}
function addShape(type){stopPlayback();change(()=>{const n=addNode(project,type);if(type==='text'&&project.background!=='#111522')n.fill='#27322b';if(type==='path'){n.width=160;n.height=100;n.pathWidth=160;n.pathHeight=100;n.fill='none';n.stroke='#f16b43';n.strokeWidth=3;n.d='M0 80 Q40 -20 80 50 T160 20';}selectedId=n.id;});setTool('select');}
function deleteSelected(){if(!canEdit())return;const name=selected().name;change(()=>{project.nodes=project.nodes.filter(n=>n.id!==selectedId);selectedId=null;});notify(`${name} deleted. Tap Undo to restore it.`);}
function duplicate(){const n=selected();if(!n)return notify('Select a layer to duplicate.');change(()=>{const copy=structuredClone(n);Object.assign(copy,{id:uid(),name:n.name+' copy',x:n.x+24,y:n.y+24,locked:false});project.nodes.push(copy);copy.keyframes=copy.keyframes.map(k=>({...k,...(Number.isFinite(k.x)?{x:k.x+24}:{}),...(Number.isFinite(k.y)?{y:k.y+24}:{})}));selectedId=copy.id;});}
function addCurrentKeyframe(){if(!canEdit())return;change(()=>addKeyframe(project,selectedId,frame));notify(`Keyframe added at frame ${frame+1}`);}
function reorder(direction){if(!canEdit())return;const i=project.nodes.findIndex(n=>n.id===selectedId),j=clamp(i+direction,0,project.nodes.length-1);if(i===j)return;change(()=>{const n=project.nodes.splice(i,1)[0];project.nodes.splice(j,0,n);});}
function download(blob,filename){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function saveProject(){download(new Blob([serializeProject(rootProject)],{type:'application/json'}),rootProject.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase()+'.rash.json');scheduleSave();notify('Project downloaded. Keep this file to edit again.');}
function modalHeader(title,subtitle=''){return `<div class="modal-header"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">×</button></div>`;}
function openModal(content,kind=''){if(playing&&kind!=='preview')stopPlayback();if(modalKind==='script'&&$('#script-input'))persistScriptDraft();closeMenu();closePanels();modalKind=kind;$('#modal-content').innerHTML=content;const dialog=$('#modal');if(!dialog.open)dialog.showModal();}
function persistScriptDraft(){const source=$('#script-input')?.value;if(source!==undefined&&source!==project.script)change(()=>project.script=source);}
function closeModal(){if(modalKind==='script')persistScriptDraft();if(modalKind==='preview'){previewSVG=null;stopPlayback();}$('#modal').close();modalKind='';}
const templateSVG=id=>sceneToSVG(createProject(id,id==='social'?'story':'web'),0);
let wizardTemplate='orbit',wizardPreset='web',wizardReplacementRequired=false;
function openNewProject(template){stopPlayback();wizardTemplate=template||'orbit';wizardPreset=template==='social'?'story':'web';newProjectDialog();}
function newProjectDialog(){wizardReplacementRequired=hasProjectWork;openModal(`${modalHeader('Every great idea starts somewhere.','Choose a canvas and a starting point. This browser keeps one current composition. Download a backup before replacing your work.')}<div class="modal-body"><div class="form-row"><div><label class="form-label" for="new-name">COMPOSITION NAME</label><input class="text-input" id="new-name" value="${esc(templates.find(t=>t.id===wizardTemplate)?.name.split(' / ')[0]||'Untitled project')}" maxlength="120"/></div><div><label class="form-label" for="new-fps">FRAME RATE</label><select id="new-fps" class="text-input"><option value="24">24 fps · Cinematic</option><option value="30" selected>30 fps · Balanced</option><option value="60">60 fps · Smooth</option></select></div></div><section><h3>Make room for your idea</h3><div class="preset-grid">${presets.map(p=>`<button class="preset-choice ${p.id===wizardPreset?'selected':''}" data-wizard-preset="${p.id}" aria-pressed="${p.id===wizardPreset}"><span class="preset-preview" style="width:${p.width/p.height>=1?26:Math.round(22*p.width/p.height)}px;height:${p.width/p.height>=1?Math.round(26*p.height/p.width):22}px"></span><strong>${esc(p.name)}</strong><small>${p.width} × ${p.height}</small></button>`).join('')}</div></section><section><h3>A little inspiration to get moving</h3><div class="template-grid">${templates.map(t=>`<button class="template-choice ${t.id===wizardTemplate?'selected':''}" data-wizard-template="${t.id}" aria-pressed="${t.id===wizardTemplate}"><div class="template-art">${templateSVG(t.id)}</div><div class="template-caption"><strong>${esc(t.name)}</strong><p>${esc(t.description)}</p></div></button>`).join('')}</div></section>${wizardReplacementRequired?'<label class="replace-consent"><input id="replace-project" type="checkbox"/> Replace the current composition and its device autosave. I have saved any work I need.</label>':''}</div><div class="modal-footer"><button class="button" data-action="save">Download current project</button><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="create-project">Create composition ${icon('plus')}</button></div>`,'new');}
function createNew(){if(wizardReplacementRequired&&!$('#replace-project')?.checked){$('#replace-project')?.focus();return notify('Download a backup, then confirm replacement of the current composition.');}const name=$('#new-name').value.trim()||'Untitled project',fps=Number($('#new-fps').value);checkpoint();editScopeId=null;scopeTrail=[];replaceDocument(createProject(wizardTemplate,wizardPreset));project.name=name;for(const n of project.nodes)for(const k of n.keyframes)k.frame=Math.round(k.frame*fps/project.fps);project.fps=fps;project.duration=fps*8;frame=0;selectedId=null;zoom=1;game=null;closeModal();commit();notify(isGame()?'Orbit collector is ready. Press Play and use arrow keys or touch.':'A fresh composition. Make it yours.');}
function renameDialog(isLayer=false){const node=selected();if(isLayer&&!canEdit())return;openModal(`${modalHeader(isLayer?'Name this layer':'Name this composition')}<div class="modal-body"><label class="form-label" for="rename-input">${isLayer?'LAYER':'COMPOSITION'} NAME</label><input id="rename-input" class="text-input" value="${esc(isLayer?node.name:rootProject.name)}" maxlength="${isLayer?100:120}" /></div><div class="modal-footer"><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="${isLayer?'confirm-layer-name':'confirm-project-name'}">Save name</button></div>`,'rename');setTimeout(()=>{$('#rename-input')?.focus();$('#rename-input')?.select();},0);}
function resizeDialog(){openModal(`${modalHeader('A canvas for every screen.','Resize the stage. Scale your artwork proportionally, or keep its current dimensions.')}<div class="modal-body"><label class="form-label" for="resize-preset">SIZE PRESET</label><select id="resize-preset" class="text-input"><option value="custom">Custom size</option>${presets.map(p=>`<option value="${p.id}">${esc(p.name)} · ${p.width} × ${p.height}</option>`).join('')}</select><div class="form-row" style="margin-top:18px"><div><label class="form-label" for="resize-width">WIDTH</label><input class="text-input" id="resize-width" type="number" min="${editScopeId?1:16}" max="${editScopeId?10000:4096}" value="${project.width}"/></div><div><label class="form-label" for="resize-height">HEIGHT</label><input class="text-input" id="resize-height" type="number" min="${editScopeId?1:16}" max="${editScopeId?10000:4096}" value="${project.height}"/></div></div><label class="property-toggle">Scale artwork to fit <input id="resize-scale" type="checkbox" checked/></label><p class="form-hint">Vector artwork stays sharp at any size. ${editScopeId?'Symbol limits are 1 to 10,000 pixels per side. Resizing updates the definition shared by all instances.':'Canvas limits are 16 to 4096 pixels per side.'}</p></div><div class="modal-footer"><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="confirm-resize">${editScopeId?'Resize symbol':'Resize composition'}</button></div>`,'resize');}
function applyResize(){const w=clamp(Number($('#resize-width').value)||1280,editScopeId?1:16,editScopeId?10000:4096),h=clamp(Number($('#resize-height').value)||720,editScopeId?1:16,editScopeId?10000:4096),scale=$('#resize-scale').checked;const ok=change(()=>{if(scale){const sx=w/project.width,sy=h/project.height,s=Math.min(sx,sy);for(const n of project.nodes){n.x*=sx;n.y*=sy;n.width*=sx;n.height*=sy;n.fontSize*=s;n.strokeWidth*=s;n.rx*=s;for(const k of n.keyframes){for(const p of ['x','width'])if(Number.isFinite(k[p]))k[p]*=sx;for(const p of ['y','height'])if(Number.isFinite(k[p]))k[p]*=sy;}}}project.width=w;project.height=h;});if(ok){zoom=1;closeModal();fitStage();}else{let error=$('#resize-error');if(!error){error=document.createElement('p');error.id='resize-error';error.className='text-danger';error.setAttribute('role','alert');$('#resize-scale').closest('label').after(error);}error.textContent=$('#toast').textContent;}}
const formats=[['png','PNG','A still image at full canvas size','IMAGE'],['svg','SVG','Crisp animated vectors','VECTOR'],['gif','GIF','An animation that goes anywhere','LOOP'],['mp4','MP4','Video for social and presentations','VIDEO'],['pdf','PDF','A first-frame snapshot, ready for print','PRINT'],['html','HTML','A self-contained animated document','WEB'],['json','Project','An editable Rash project file','SOURCE']];
let chosenFormat='svg',exporting=false;
function exportDialog(){chosenFormat='svg';openModal(`${modalHeader('Let your ideas out.','Export the complete scene and its symbol library, or embed it on your own site.')}<div class="modal-body"><div class="format-grid">${formats.map(([id,name,description,tag])=>`<button class="format-choice ${id===chosenFormat?'selected':''}" data-format="${id}" aria-pressed="${id===chosenFormat}"><strong>${name}<small>${tag}</small></strong><p>${description}</p></button>`).join('')}</div><div class="export-summary"><span>${esc(rootProject.name)}</span><span>${rootProject.width} × ${rootProject.height}</span><span>${rootProject.fps} fps</span><span>${(rootProject.duration/rootProject.fps).toFixed(1)} seconds</span></div><p class="code-info" id="format-note">SVG preserves your vector artwork and animation. No player installation required.</p><p id="export-progress" class="export-progress" role="status"></p></div><div class="modal-footer"><button class="button" data-action="share">${icon('code')} Embed instead</button><button class="button primary" id="download-export" data-action="download-export">${icon('export')} Export SVG</button></div>`,'export');}
async function doExport(){if(exporting)return;exporting=true;const b=$('#download-export'),status=$('#export-progress');b.disabled=true;status.classList.remove('error');status.textContent='Preparing your composition…';const snapshot=cloneProject(rootProject);try{const result=await exportProject(snapshot,chosenFormat,{onProgress:value=>{if(status.isConnected)status.textContent=typeof value==='string'?value:`Rendering ${Math.round(Number(value)*100)}%…`;}});download(result.blob,result.filename);if(status.isConnected)status.textContent=`${result.filename} is ready. Your download has started.`;notify(`Exported ${chosenFormat.toUpperCase()}`);}catch(e){if(status.isConnected){status.classList.add('error');status.textContent=e.message||'Export was not available in this browser.';}}finally{exporting=false;if(b.isConnected)b.disabled=false;}}
function shareDialog(){let code;try{code=embedCode(rootProject,{baseURL:new URL('./',location.href).href});}catch(e){code=`Embed generation failed: ${e.message}`;}openModal(`${modalHeader('Made here. Played everywhere.','Add Rash to your website with a self contained, isolated player.')}<div class="modal-body"><label class="form-label" for="embed-code">JAVASCRIPT EMBED</label><textarea id="embed-code" class="embed-code" rows="9" readonly spellcheck="false">${esc(code)}</textarea><p class="code-info">Paste into an HTML page. The player scales to its container and keeps scene scripts isolated from the host page. Your project data is included in the snippet.</p><div class="export-summary"><span>Responsive SVG</span><span>Browser playback</span><span>No account required</span></div><button class="text-link" data-action="preview">Preview this composition ↗</button></div><div class="modal-footer"><span class="footer-note">Need a file? Export HTML for a standalone player.</span><button class="button" data-action="download-embed">Download snippet</button><button class="button primary" data-action="copy-embed">${icon('copy')} Copy embed code</button></div>`,'share');}
function previewDialog(){stopPlayback();openModal(`${modalHeader('A little motion goes a long way.',isGame()?'Use arrow keys, WASD or touch the stage. Collect the green signals.':'Your composition, without the editing tools.')}<div class="preview-shell"><svg id="preview-stage" xmlns="${NS}" aria-label="Composition preview"></svg></div><div class="modal-footer preview-footer"><span class="preview-time" id="preview-time">${timecode()}</span><div style="display:flex;gap:8px"><button class="button" data-action="reset-preview">${icon('loop')} Restart</button><button class="button primary" id="preview-play" data-action="play">${icon('play')} Play</button></div></div>`,'preview');previewSVG=$('#preview-stage');renderStage();if(isGame()){previewSVG.style.touchAction='none';previewSVG.addEventListener('pointerdown',e=>{gameInput.target=pointFromEvent(e,previewSVG);});previewSVG.addEventListener('pointermove',e=>{if(e.buttons||e.pointerType==='touch')gameInput.target=pointFromEvent(e,previewSVG);});}togglePlayback();}
