let timelineDrag=false;$('#timeline-svg').addEventListener('pointerdown',event=>{stopPlayback();const cameraKey=event.target.closest('[data-camera-keyframe]');if(cameraKey){timelineDrag=false;seek(Number(cameraKey.dataset.cameraKeyframe));cameraDialog();return;}timelineDrag=true;const key=event.target.closest('[data-keyframe]');if(key){selectNode(key.dataset.node);seek(Number(key.dataset.keyframe));}else{const r=$('#timeline-svg').getBoundingClientRect();seek((event.clientX-r.left-12)/(r.width-24)*(project.duration-1));}$('#timeline-svg').setPointerCapture(event.pointerId);});$('#timeline-svg').addEventListener('pointermove',event=>{if(!timelineDrag)return;const r=$('#timeline-svg').getBoundingClientRect();seek((event.clientX-r.left-12)/(r.width-24)*(project.duration-1));});$('#timeline-svg').addEventListener('pointerup',()=>timelineDrag=false);$('#timeline-svg').addEventListener('pointercancel',()=>timelineDrag=false);
const editable=el=>el?.matches?.('input,textarea,select,[contenteditable="true"]');
document.addEventListener('keydown',event=>{const key=event.key.toLowerCase(),ctrl=event.ctrlKey||event.metaKey;if(key==='escape'){finishLiveEdit();closeMenu();closePanels();if(!$('#modal').open){selectNode(null);setTool('select');}return;}if(editable(event.target)){if(event.target.id==='rename-input'&&event.key==='Enter'){event.preventDefault();actions[modalKind==='rename'&&$('#modal [data-action="confirm-layer-name"]')?'confirm-layer-name':'confirm-project-name']?.();}if(event.target.id==='command-input'&&event.key==='Enter')$('#command-list button')?.click();if(event.target.id==='script-input'&&event.key==='Tab'){event.preventDefault();const el=event.target,start=el.selectionStart,end=el.selectionEnd;el.setRangeText('  ',start,end,'end');}return;}
 if($('#modal').open&&modalKind!=='preview')return;
 if(playing&&isGame()){const map={arrowleft:'left',a:'left',arrowright:'right',d:'right',arrowup:'up',w:'up',arrowdown:'down',s:'down'};if(map[key]){event.preventDefault();gameInput[map[key]]=true;delete gameInput.target;return;}}
 if(playing&&key!==' ')stopPlayback();
 if(ctrl){const map={z:event.shiftKey?'redo':'undo',y:'redo',d:'duplicate',s:'save',k:'commands',n:'new-project'};if(map[key]){event.preventDefault();actions[map[key]]();return;}if(key==='c'&&selected()){clipboard=structuredClone(selected());event.preventDefault();return;}if(key==='v'&&clipboard){event.preventDefault();change(()=>{const n=structuredClone(clipboard),id=uid();Object.assign(n,{id,x:clipboard.x+24,y:clipboard.y+24,name:clipboard.name+' copy',locked:false});project.nodes.push(n);n.keyframes=n.keyframes.map(k=>({...k,...(Number.isFinite(k.x)?{x:k.x+24}:{}),...(Number.isFinite(k.y)?{y:k.y+24}:{})}));selectedId=id;});return;}}
 if(key===' '){event.preventDefault();togglePlayback();return;}if(key==='delete'||key==='backspace'){event.preventDefault();deleteSelected();return;}if(key==='?'||key==='/'){event.preventDefault();helpDialog();return;}if(key==='k'||event.key==='F6'){event.preventDefault();addCurrentKeyframe();return;}if(['arrowleft','arrowright','arrowup','arrowdown'].includes(key)&&selected()){event.preventDefault();if(selected().locked)return;const n=currentNode(),amount=event.shiftKey?10:1;change(()=>{if(key==='arrowleft')setNodeProperty('x',n.x-amount);if(key==='arrowright')setNodeProperty('x',n.x+amount);if(key==='arrowup')setNodeProperty('y',n.y-amount);if(key==='arrowdown')setNodeProperty('y',n.y+amount);});return;}const tools={v:'select',r:'rect',o:'ellipse',t:'text',p:'path',h:'hand'};if(tools[key])setTool(tools[key]);if(event.key==='Enter'&&event.target.matches('[data-layer]'))selectNode(event.target.dataset.layer);
});
document.addEventListener('keyup',event=>{const map={arrowleft:'left',a:'left',arrowright:'right',d:'right',arrowup:'up',w:'up',arrowdown:'down',s:'down'};if(map[event.key.toLowerCase()])gameInput[map[event.key.toLowerCase()]]=false;});
window.addEventListener('blur',()=>{gameInput={left:false,right:false,up:false,down:false};});
function syncViewport(){const vv=window.visualViewport;document.documentElement.style.setProperty('--viewport-height',`${vv?.height||innerHeight}px`);document.documentElement.classList.toggle('keyboard-open',isMobile()&&editable(document.activeElement)&&(innerHeight-(vv?.height||innerHeight)>100));if(!isMobile())closePanels();requestAnimationFrame(()=>{fitStage();renderTimeline();renderStage();});}
window.addEventListener('resize',syncViewport);window.visualViewport?.addEventListener('resize',syncViewport);document.addEventListener('focusin',syncViewport);document.addEventListener('focusout',syncViewport);syncViewport();
document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing)stopPlayback();});
$('#drawing-tools').innerHTML=[['select','Select','V'],['rect','Rectangle','R'],['ellipse','Ellipse','O'],['text','Text','T'],['path','Freehand','P'],['hand','Pan','H']].map(([id,label,key],i)=>`${i===5?'<div class="rail-divider"></div>':''}<button class="tool-button ${id==='select'?'active':''}" data-tool="${id}" aria-label="${label} tool" title="${label} (${key})">${icon(id)}</button>`).join('');
$('#shape-library').innerHTML=[['rect','Rectangle'],['ellipse','Ellipse'],['text','Text'],['path','Curve']].map(([id,label])=>`<button data-shape="${id}" title="Add ${label}" aria-label="Add ${label}">${icon(id==='path'?'pen':id)}</button>`).join('');
for(const [sel,i] of [['.command-button','command'],['[data-action="add-layer"]','plus'],['#grid-button','grid'],['.rail-bottom [data-action="script"]','code'],['.rail-bottom [data-action="help"]','help'],['#timeline-icon','timeline'],['#loop-button','loop'],['[data-action="first-frame"]','first'],['[data-action="last-frame"]','last'],['#play-button','play'],['.history-actions [data-action="undo"]','undo'],['.history-actions [data-action="redo"]','redo'],['[data-action="timeline-size"]','expand']]){const el=$(sel);if(el)el.innerHTML=icon(i);}
$('.preview-button').innerHTML=`${icon('play')} Preview`;$('.export-button').innerHTML=`${icon('export')} Export`;
render();renderLibrary();
createRuntime().then(r=>{runtime=r;$('#engine-status').textContent=r.kind==='rust-wasm-worker'?'Rust / WASM worker':r.kind;const tag=$('#script-engine');if(tag)tag.textContent=r.kind;}).catch(e=>{runtimeError=e.message;$('#engine-status').textContent='Script runtime unavailable';});
